let input = "42";

loop {
    let guess: u32 = match input.trim().parse() {
        Ok(num) => num,
        ___ => continue,
    };
    println!("입력한 숫자: {guess}");
    break;
}

fn main() {
    let mut n = 0;
    loop {
        n += 2;
        if n >= 5 {
            break;
        }
    }
    println!("{n}");
}

fn main() {
    let mut sum = 0;
    for token in ["1", "둘", "3"] {
        let value: i32 = match token.parse() {
            Ok(v) => v,
            Err(_) => continue,
        };
        sum += value;
    }
    println!("{sum}");
}
